describe('构建产物退役 openspec 清理', () => {
  const ASSEMBLE_TIMEOUT = 30_000;

  it(
    '三平台 outDir 中不存在 bin/openspec、bin/openspec-bundled.js、bin/openspec.cmd',
    async () => {
      await runAssembleAll();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
