describe('MCP 注册 — registerTool spy 精确字面量', () => {
  const REGISTER_ORDER = [
    'phase_log',
    'archi_query',
    'archi_validate',
    'archi_write',
    'archi_check',
    'archi_decide',
    'phase_next',
    'config_get',
    'test_detect_frameworks',
    'test_resolve_paths',
    'change_list',
    'change_create',
