        timestamp: new Date(Date.now() + i).toISOString(),
        backtrack_to: i % 2 === 1 ? 'proposal' : null,
        report: '',
        checklist: [],
      });
    }
    const result = next(windowEntries, 'test-change', undefined, 'round-limit-s4');
    expect(result.error).toBe('round_limit_exceeded');
